    if (pair_ij_mapping == pair_kl_mapping && task_ij0+256 <= task_kl0) return;

    int sq_id = threadIdx.x;
    int gout_id = threadIdx.y;
    int t_id = gout_id * 64 + sq_id;
    int tx = sq_id % 16;
