    double *dm_ij_cache = shm + 1360 + tx;
    double *vj_cache = shm + 1280 + t_id;
    double *Rt = shm + 1680 + sq_id;

    for (int n = t_id; n < 1120; n += 256) vj_kl_cache[n] = 0.;
    __syncthreads();

    for (int n = t_id; n < 32; n += 256) {
        int task_kl = blockIdx.y * 32 + n;
        if (task_kl < npairs_kl) {
            int pair_kl = pair_kl_mapping[task_kl];
            int ksh = pair_kl / nbas;
            int lsh = pair_kl % nbas;
            double ak = env[bas[ksh*BAS_SLOTS+PTR_EXP]];
            double al = env[bas[lsh*BAS_SLOTS+PTR_EXP]];
            double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
            double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
            double akl = ak + al;
            double iakl = 1. / akl;
            Rq_cache[n+0] = (ak * rk[0] + al * rl[0]) * iakl;
            Rq_cache[n+32] = (ak * rk[1] + al * rl[1]) * iakl;
            Rq_cache[n+64] = (ak * rk[2] + al * rl[2]) * iakl;
            Rq_cache[n+96] = akl;
            s_iakl[n] = iakl;
        } else {
            Rq_cache[n+0] = 1e5;
            Rq_cache[n+32] = 1e5;
            Rq_cache[n+64] = 1e5;
            Rq_cache[n+96] = 1.;
            s_iakl[n] = 1.;
        }
    }

    for (int batch_ij = 0; batch_ij < 16; ++batch_ij) {
        int task_ij0 = (blockIdx.x * 16 + batch_ij) * 16;
        if (task_ij0 >= npairs_ij) break;
        float q_ij_batch = q_cond[pair_ij_mapping[task_ij0]];
        __syncthreads();
        if (t_id < 16) {
            int task_ij = task_ij0 + t_id;
            if (task_ij < npairs_ij) {
                int pair_ij = pair_ij_mapping[task_ij];
                int ish = pair_ij / nbas;
                int jsh = pair_ij % nbas;
                double ai = env[bas[ish*BAS_SLOTS+PTR_EXP]];
                double aj = env[bas[jsh*BAS_SLOTS+PTR_EXP]];
                double *ri = env + bas[ish*BAS_SLOTS+PTR_BAS_COORD];
                double *rj = env + bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
                double aij = ai + aj;
