    int gout_id = threadIdx.y;
    int t_id = gout_id * 64 + sq_id;
    int tx = sq_id % 16;
    int ty = sq_id / 16;
    unsigned int lane_id = t_id % 32;
    unsigned int group_id = lane_id / 16;
    unsigned int mask = 0xffffu << (group_id * 16);

    extern __shared__ double shm[];
    double *vj_kl_cache = shm;
    double *Rq_cache = shm + 320;
    double *s_iakl = shm + 448;
    double *Rp_cache = shm + 480;
    double *s_iaij = shm + 544;
    double *dm_ij_cache = shm + 560 + tx;
    double *vj_cache = shm + 480 + t_id;
    double *Rt = shm + 1120 + sq_id;

    for (int n = t_id; n < 320; n += 256) vj_kl_cache[n] = 0.;
