            int lsh = pair_kl % nbas;
            double ak = env[bas[ksh*BAS_SLOTS+PTR_EXP]];
            double al = env[bas[lsh*BAS_SLOTS+PTR_EXP]];
            double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
            double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
            double akl = ak + al;
            double iakl = 1. / akl;
            Rq_cache[n+0] = (ak * rk[0] + al * rl[0]) * iakl;
            Rq_cache[n+32] = (ak * rk[1] + al * rl[1]) * iakl;
            Rq_cache[n+64] = (ak * rk[2] + al * rl[2]) * iakl;
            Rq_cache[n+96] = akl;
            s_iakl[n] = iakl;
        } else {
            Rq_cache[n+0] = 1e5;
            Rq_cache[n+32] = 1e5;
